const rows = $input.all();

const run = $('Create Collector Run').all(0, $runIndex)[0].json;

return rows.map((item, index) => {
  const raw = item.json;
  const normalized = {};

  for (const [key, value] of Object.entries(raw)) {
    // 清理 CSV 第一列表头可能存在的 UTF-8 BOM，以及字段名前后空格
    const cleanKey = key.replace(/^\uFEFF/, '').trim();

    if (typeof value === 'string') {
      const cleanValue = value.trim();
      normalized[cleanKey] = cleanValue === '' ? null : cleanValue;
    } else {
      normalized[cleanKey] = value;
    }
  }

  // rating 显式转数字
  if (normalized.rating !== null && normalized.rating !== undefined) {
    normalized.rating = Number(normalized.rating);
  }

  // 提前阻止脏数据进入 PostgreSQL
  if (!normalized.platform) {
    throw new Error(
      `第 ${index + 1} 行缺少 platform；原始字段名：${Object.keys(raw).join(', ')}`
    );
  }

  return {
    json: {
      ...normalized,

      collector_run_id: run.run_id,
      source_row_no: index + 1,

      source_file_name: run.source_file_name,
      source_file_sha256: run.source_file_sha256,

      source_row_json: JSON.stringify(raw),
    }
  };
});

const items = $input.all();

if (items.length === 0) {
  throw new Error('没有任何 Staging 行写入，无法将采集任务标记为 SUCCESS');
}

const runId = items[0].json.collector_run_id;

return [
  {
    json: {
      run_id: runId,
      rows_loaded: items.length
    }
  }
];

const input = $input.first()?.json ?? {};

const payload =
  input.body && typeof input.body === 'object'
    ? input.body
    : input;

const requiredFields = [
  'source_name',
  'source_platform',
  'collection_scope',
  'run_slot',
  'query_start_date',
  'query_end_date',
  'file_name',
];

for (const field of requiredFields) {
  if (
    payload[field] === undefined ||
    payload[field] === null ||
    String(payload[field]).trim() === ''
  ) {
    throw new Error(`${field} is required`);
  }
}

const fileName = String(payload.file_name).trim();

if (
  fileName.includes('/') ||
  fileName.includes('\\') ||
  !fileName.toLowerCase().endsWith('.csv')
) {
  throw new Error('invalid file_name');
}

const datePattern = /^\d{4}-\d{2}-\d{2}$/;

if (!datePattern.test(payload.query_start_date)) {
  throw new Error('invalid query_start_date');
}

if (!datePattern.test(payload.query_end_date)) {
  throw new Error('invalid query_end_date');
}

const runSlot = String(payload.run_slot).toUpperCase();

if (!['MORNING', 'AFTERNOON'].includes(runSlot)) {
  throw new Error('invalid run_slot');
}

return [
  {
    json: {
      source_name: String(payload.source_name).trim(),
      source_platform: String(payload.source_platform).trim(),

      query_shop_name:
        payload.query_shop_name &&
        String(payload.query_shop_name).trim() !== ''
          ? String(payload.query_shop_name).trim()
          : null,

      collection_scope: String(payload.collection_scope).trim().toUpperCase(),

      timezone: payload.timezone || 'Asia/Shanghai',
      run_slot: runSlot,

      query_start_date: payload.query_start_date,
      query_end_date: payload.query_end_date,

      file_name: fileName,
    },
  },
];

const items = $input.all();

const rows = items.map(item => item.json ?? {});

const alreadyProcessedCount = rows.filter(
  row => row.already_processed === true
).length;

return [
  {
    json: {
      workflow: 'VOC_00_CSVLoader_v1',
      status: 'SUCCESS',

      input_item_count: items.length,
      already_processed_count: alreadyProcessedCount,

      // 即使这一次没有新文件，也继续跑下游。
      // 因为 VOC_01 / VOC_02 可能还有上一次留下的 pending 数据需要恢复处理。
      continue_pipeline: true,

      completed_at: new Date().toISOString()
    }
  }
];
